quests[41055] = { id = 41055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Payback" }
quests[41056] = { id = 41056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love Lost", description = "Malfurion, my love...\n\nIn vision I saw him, enraged and then distressed, and now lost beyond my mind's reach.\n\nHe is strong, but the horrors that have befallen this land are all-consuming.\n\nI must find him, and you must help me!\n\nGather your wits, {race}, and follow me.", completion = "I pray it is not too late, friend.", objectives = "Speak to Tyrande Whisperwind at Starsong Refuge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41057] = { id = 41057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Payback" }
quests[41058] = { id = 41058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forge of Guardians", description = "First and foremost, the Forge of the Guardian must be protected. With Kathra'natir's knowledge, it will no longer be safe in Violet Hold.\n\nTogether, we should be able to transport it to a safer place. From there, our true challenge can begin.You will learn:", objectives = "Help Meryl and Alodi transport the Forge of the Guardian to a safe location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41059] = { id = 41059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: Odyn's Cauldron", description = "Your actions in Stormheim were courageous. I thank you for avenging me, and for helping my apprentice, Aegira. I can think of none better to inherit my knowledge.\n\nWith you, I will share the secret to my Storm Brew. The true strength of the brew comes from Odyn's Cauldron, which can be found in the great hall just ahead.\n\nYou have my blessing to borrow it. Good luck in your journey ahead, {name}.", progress = "Did you pass the trials?", completion = "Tell me, were the Halls of Valor as amazing as the stories say? Regardless, you got the cauldron. Now we can begin brewing.", objectives = "Collect Odyn's Cauldron from the Halls of Valor, then pass Odyn's trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41060] = { id = 41060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbridled Power", description = "Although our forces have dutifully held this citadel since your departure, we have been unable to access most of its resources - the Fel Hammer can only be fully activated by those bearing the mark of a Legion lord.\n\nThankfully, your blades carry that very mark. Use them to activate the Fel Hammer - show your forces your limitless power!", progress = "Yes?", completion = "The Fel Hammer is ours at last.\n\nNicely done.", objectives = "Activate the Fel Hammer and rally your Illidari forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41062] = { id = 41062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spoils of Victory", description = "The Fel Hammer will be a fine home for our kind, but it is what we found within its depths that is the true prize of our conquest.\n\nBattlelord Gaardoun and his Ashtongue have it closely guarded - you should have him show you.", completion = "It is my honor to serve, {name}.", objectives = "Have Battlelord Gaardoun show you what your forces obtained.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41064] = { id = 41064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Forge of the Nathrezim", description = "Even as we speak, the Legion's dark masters fashion new horrors in hopes that they might destroy us - especially you.\n\nYou must increase your own power as well.\n\nThe Cursed Forge of the Nathrezim, our greatest treasure from taking the Fel Hammer, waits in the chamber ahead. You can use it to further empower your blades and maintain our edge over the enemy.", progress = "Your blades... they glow with such power...", completion = "Such power! The Legion's armies will fall before you in droves.", objectives = "Use the Cursed Forge of the Nathrezim to empower your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41065] = { id = 41065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troubling News", description = "Master, there is one more thing I wish to speak to you about.\n\nBelow us lies an open chamber cut off from the rest of the citadel. We thought you might desire it as your personal sanctum - a place where you might gather your thoughts or scry upon your enemies.\n\nThe sanctum crystal before you will transport you there - Lady S'theno has already descended to help you get acquainted.", objectives = "Use the Sanctum Crystal to enter the Master's Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41066] = { id = 41066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Gaze", description = "{name}, before you lies your nether crucible - more powerful than any we've crafted before.\n\nThe souls of the hundreds of slain demons in Mardum have provided us with enough power to directly observe the Legion on Azeroth.\n\nWhat we have uncovered so far has been... unsettling. Gaze into the pool and see for yourself.", progress = "The Legion threat is more dire than we thought.", completion = "We must not underestimate the Legion - I fear they are even more powerful than we realize.", objectives = "Use the Empowered Nether Crucible to gaze upon the Burning Legion's forces in Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41067] = { id = 41067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time is of the Essence", description = "As you can see, there is little time to spare - the Legion's armies already encroach on our world.\n\nKayn has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", completion = "<Kayn sighs.>\n\nI know that look. I, too, gazed into the crucible and saw the horrors of the tomb.\n\nWe must act quickly.", objectives = "Speak to Kayn Sunfury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41069] = { id = 41069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direct Our Wrath", description = "We must seal the Tomb of Sargeras at all costs or the flow of demons will never cease.\n\nUntil then, we must do what we can on the ground to alleviate their foothold before it grows further.\n\nThis citadel was created to spearhead Legion invasions on other worlds - we can use its navigation systems to plan our assault.\n\nI think you would agree that none would be better suited to lead our charge than you.", completion = "Agreed. You are as skilled a tactician as myself.", objectives = "Select your first assault point on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41070] = { id = 41070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spoils of Victory", description = "In conquering this citadel we obtained something that I think would be of great use to you.\n\nGaardoun's men have it well-guarded just below - I suggest you have him show you.", completion = "It is my honor to serve, {name}.", objectives = "Have Battlelord Gaardoun show you what your forces obtained.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
