quests[41084] = { id = 41084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reward: Ebonchill" }
quests[41085] = { id = 41085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mage's Weapon", description = "It is decided, then.\n\nThe foundation of the Tirisgarde's strength lies in the ancient artifacts wielded by its champions. Your first task will be to retrieve one such artifact.\n\nThe master appendix of this library lists every artifact known to the Council of Tirisfal. There should be a few choices in there worth looking into.\n\nI will leave it to you to choose which to pursue.", completion = "This is a wise choice. \n\nIt should serve you well in our hunt for Kathra'natir.", objectives = "Use the Appendix of Azerothian Artifacts to choose an artifact to pursue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41086] = { id = 41086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Peaceful World", description = "Word has reached us that the Legion is advancing on the Broken Isles.\n\nThey beset us from all sides, and if we do not stand strong, they will spill over into the rest of Azeroth.\n\n{name}, we need your help more than ever. Lend your strength to those defending at the front. We cannot fail here.", completion = "Astounding, Grandmaster! Reports are flying in about your success. Without your help, many of our outposts around the Broken Isles would have fallen.", objectives = "Complete 10 World Quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41087] = { id = 41087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm Brew", description = "Grandmaster, the Legion is attacking the Wandering Isle!\n\nWe sent defenders up to the Ridge of Laughing Winds, but they can't hold for long.\n\nOur only chance is to finish making the Storm Brew. Chen and Aegira have already gone up to the Chamber of Whispers, but they are under heavy attack as well.\n\nSpeak to Tak Tak and take a kite up to join them at once!", completion = "I don't know about you, Grandmaster, but I think we should take a well-earned rest after all of this.", objectives = "Take Tak-Tak's kite to the Ridge of Laughing Winds, help Chen Stormstout & Aegira make the Storm Brew, and defeat the Burning Legion's forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41089] = { id = 41089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lords of the Hills" }
