quests[41093] = { id = 41093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DANGER: Durguth" }
quests[41094] = { id = 41094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatchlings of the Talon", description = "Greetings, hatchling. Do you wish to soar amongst the clouds as my children do?\n\n<Aviana chuckles - a clicking, crow-like noise.>\n\nVery well, receive my blessing and we shall see how developed your wings are.", objectives = "Talk to Aviana to receive her blessing, then complete her challenge by collecting Emerald Globes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41095] = { id = 41095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Critical Crops" }
quests[41096] = { id = 41096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time is of the Essence", description = "As you can see, there is little time to spare - the Legion's armies already encroach on our world.\n\nAltruis has gathered our best tacticians around the star map above us to discuss our plan of attack - your leadership would be invaluable to their efforts.", completion = "<Altruis nods knowingly.>\n\nI saw it too.\n\nWe must consider our next move carefully.", objectives = "Speak to Altruis the Sufferer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41097] = { id = 41097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shard of Vorgos", description = "According to the wyrmtongue servant, there is a portal that will take you into the Burning Legion command ship. However, the portal is locked to those without the keys.\n\nThe first key shard is held by an Ered'ruin known as Vorgos. He resides within the Fel Breach, which is at the end of the Arcway.\n\nSlay Vorgos and place the key shard into its position next to the portal.", progress = "<The Shard of Vargos pulses in your hand.>", completion = "<The Shard of Vorgos locks into position next to the portal. Swirling fel energy collects around the shard, filling the room with an ominous, dark presence.>", objectives = "Collect the Shard of Vorgos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41098] = { id = 41098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shard of Kozak", description = "The demon leading the operation in Felsoul Hold is an eredar named Azoran. In order to get to him, we will need to open a portal to the Burning Legion command ship.\n\nAzoran has a demon jailer in his service known as Kozak the Afflictor.\n\nKozak the Afflictor holds one of the key shards necessary to open a portal to the ship. He can be found in the prison quarters known as the Halls of the Eclipse in the lower portion of Felsoul Hold.\n\nSlay Kozak and place his key shard next to the portal.", progress = "<The Shard of Kozak tugs as if it wants to fly into place.>", completion = "<The Shard of Kozak locks into position next to the portal. You can feel the dark writhing of fel energy surround you as it collects near the portal.>", objectives = "Collect the Shard of Kozak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41099] = { id = 41099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direct Our Wrath", description = "The Tomb of Sargeras is the Legion's primary entrance into our world - it must be destroyed.\n\nNo easy task, but until we have the means to do so we must do what we can to stop their invasion.\n\nThe Legion used this citadel to spearhead invasions on other worlds - we can use its navigation systems to plan our own assault against them.\n\nYou, of course, must take the honor of first breaking ground on their territory, but we will soon follow.", completion = "Well-chosen. The Legion will soon fear the very sight of the Illidari on the battlefield.", objectives = "Select your first assault point on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41100] = { id = 41100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Swap Didis" }
quests[41101] = { id = 41101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady S'theno Calls", description = "Master {name}, I have completed my reconnaissance in Dalaran as you asked.\n\nI await your return at the Fel Hammer.", objectives = "Use your Gateway: The Fel Hammer ability to return to the Fel Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41102] = { id = 41102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trusted Lieutenant", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41103] = { id = 41103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleashed Havoc", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41105] = { id = 41105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sword of Kings", description = "The first king of the humans, Thoradin, performed many acts of heroism and valor. While on a personal quest near the end of his reign, he stumbled upon the tomb of my brother Tyr... and the grave-prison of the monstrosity he died fighting. Thoradin unintentionally awoke the beast and gave his life to keep it from escaping.\n\nIt is Thoradin's sword, Strom'kar, that has kept the monster at bay. Retrieve it and finish what Tyr and Thoradin started. Kill Zakajz the Corrupted.", progress = "Ah, you have returned...", completion = "A mighty blade! Forged by the son of vrykul, enchanted by elven sorcery, and quenched in the blood of a C'thraxxi. It will serve you well, {name}. With it, you will put an end to our enemies!", objectives = "Find Strom'kar, the Warbreaker and deal with Zakajz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41106] = { id = 41106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Wilds", description = "Beating the Legion requires us to strike quickly and unexpectedly.\n\nWe have discovered a Dreamway by which we can travel through the Emerald Dream itself. Though only a short walk through the Dream, it will allow us to cross vast distances on Azeroth and even access the ancient home of all druids, Val'sharah.\n\nMalfurion is preparing the ritual to open the Dreamway. I need you to summon Zen'tabra and Naralex to his side.\n\nOnly by combining our efforts can we hope to succeed.", progress = "This ritual must succeed, {name}.", completion = "Good, soon the ritual will be ready to begin.", objectives = "Locate Zen'tabra and Naralex, and direct them to the ritual site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41107] = { id = 41107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Apples", description = "That fruit over there? That's a pale imitation to what I can grow.\n\nBut that accursed Daglir somehow manages to gain the favor of the courts, so we must dine on mediocrity!\n\nWe must teach Daglir a lesson for stealing my crop, but we must be discreet.\n\nOutside the shield grows a purple flower called Shadowbloom. Fetch some for me and we'll make sure that he pays dearly for his insolence!", progress = "I would avoid eating any food until you've washed your hands.", completion = "Excellent. This will be enough for my purposes.", objectives = "Gather 8 Shadowbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41108] = { id = 41108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rain Death Upon Them", description = "Aboard the hippogryph you now possess a unique opportunity. It is time for the Nightborne to regret letting you live.", objectives = "Slay 50 Nightborne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41109] = { id = 41109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waiting for Revenge", description = "The Volatile Spell Focus hums with energy as you hold it. Handle with care! \n\nOnly with this item in your possession will the Hippogryphs allow themselves to be mounted.", objectives = "Mount a Hippogryph.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41110] = { id = 41110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waiting for Revenge", description = "The Hippogryph eyes you curiously, searching your hands.", objectives = "Mount the Hippogryph.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41111] = { id = 41111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rain Death Upon Them", description = "The hippogryph before you presents a unique opportunity. It is time for the Nightborne to regret letting you live.", objectives = "Slay 50 Nightborne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41112] = { id = 41112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Akazamzarak", description = "There is a goblin who is a master of portals and teleportation by the name of Akazamzarak. His talents have gone mostly unnoticed, however, since he mostly uses them for chicanery.\n\nHe is, what you would call, a street performer.\n\nFortunately for us, he is performing in the streets of Dalaran, grifting coins from the unenlightened masses.\n\nTake this bag of gold. See if you can convince him to change vocations.", completion = "You could say you've got my attention, pal!\n\nSo you're looking to hire me on full-time, eh? Well if the future payoffs are anything like this, I'd say you've got yourself a deal.", objectives = "Place the Sizeable Pouch of Gold in Akazamzarak's tip bucket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41113] = { id = 41113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Way to Travel", description = "Portals? Teleportation? You bet I can help you out with that! I mean, how do you think I pull the rabbit out of...\n\n...um, you didn't hear that.\n\nAnyway, I can help you move your mages around, if the price is right. Heck I can even teach those combat mages a thing or two. Ever been on the receiving end of an exploding bunny? It ain't pretty!\n\nFor starters, let me whip up a portal to take us to this hall you're talking about.", completion = "I understand he may be unconventional, but I think this goblin is exactly what we'll need to quickly get this new Tirisgarde up to snuff for the task at hand.\n\nI've already sent word to many talented mages who can help. They await transportation to the Hall, where they can begin their new purpose.\n\nShall we?", objectives = "Return to Meryl Felstorm in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41114] = { id = 41114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion's Return", description = "I can sense the power of the artifact you hold. It will do well against the Legion as it is, but we have the ability to unlock its power even further. \n\nYou must return to the Hall of the Guardian. You can use the incantation I taught you before to pass through the runes.", completion = "You learn quickly, {name}. \n\nI think Kathra'natir will rue the day he made you his enemy.", objectives = "Teleport to the Hall of the Guardian and return to Meryl Felstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41115] = { id = 41115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Chen Stormstout", objectives = "I am honored to have fought by your side at the Peak of Serenity, {name}. Your leadership will help us greatly in the fight against the Legion.\n\nI would like to fight for you, if you would have me as a champion. I believe my skills as a brewer may also be of service to the order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41116] = { id = 41116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Artifacts - Shaman - Puzzle Room - Treasure - DGK" }
quests[41117] = { id = 41117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seen Thalrenus Iceblock Shenanigans" }
quests[41119] = { id = 41119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt", description = "You must lead this hunt, {name} - a small force will join you to ensure Varedis meets his end.\n\nYou must try to make it into Varedis' hold undetected; the less time you spend in Legion territory the better.\n\nMeet at Krasus' Landing when you are prepared to leave.", completion = "What of the others? Did they...?\n\nI see. They gave their lives for a worthy cause - the Twinblades will change the tide of this war, mark my words.", objectives = "Obtain the Twinblades of the Deceiver from Varedis Felsoul in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41120] = { id = 41120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Arrangements", description = "Do you remember Varedis? He was once our lead trainer at the Black Temple, but fell early in the siege.\n\n...or so we thought.\n\nKor'vas spotted the traitor amongst the Legion wielding glaives imbued with power unlike anything she'd ever seen.\n\nThe Kirin Tor have an eredar lord interred in the Violet Hold that will know where Varedis' base of operations is. The hold's warden has agreed to consider granting us access to him.\n\n<Altruis smirks.>\n\nTime to play the friendly diplomat.", completion = "Let's get this done with. These bureaucrats already test my patience.", objectives = "Meet Altruis the Sufferer outside the Violet Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41121] = { id = 41121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Any Means", description = "We need to find out Varedis' location from the eredar inside this prison - the kind warden and his men here are all that stand in our way.\n\nWe'll take them on together if need be - whatever it takes.", progress = "Well done.", completion = "Suramar? That is only a short flight from here.", objectives = "Gain entrance to the Violet Hold and interrogate Taldath the Destroyer to find out the location of the traitor Varedis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41122] = { id = 41122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists Take You" }
quests[41123] = { id = 41123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Artisan's Mark", description = "You there! Do you have a moment?\n\nI need you to meet with my friend in the Promenade and retrieve a signet ring. I would send my oaf of an apprentice, but he is not finished with the simple task I gave him.\n\nI am expecting a guest at any moment and I simply must have it before he arrives. Can you help me, friend?", progress = "Do you have it?", completion = "Oh, thank the Magistrix! I was worried it was lost forever.\n\nI see that this ring has seen some... use. I do hope it doesn't belong to anyone important. Or... vocal.", objectives = "Obtain Lespin's Signet Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41124] = { id = 41124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tirisgarde Reborn", description = "The Tirisgarde is reformed.  It is time we begin our mission in earnest.\n\nThe order will need leaders, and though I may be an experienced mage,  I am no strategist. You have proven yourself capable, in both your past exploits and present. \n\nWill you take on this challenge, {name}?", completion = "So you're a Conjuror now, huh? Fan-cy!\n\nWe've got a good start with this Tirisgarde thing here, but I think we should keep up the recruiting if we actually plan on invading demon-town.\n\nFortunately for you, nobody negotiates contracts like a goblin!", objectives = "Receive your new title from Meryl Felstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41125] = { id = 41125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocked Potential", description = "In ancient times, the Forge of the Guardian was used to channel the power of the Council of Tirisfal into one mage, creating a Guardian. But this is not its only use.\n\nIt also serves as a font of arcane energy which can be used to manipulate and empower the artifacts of this world. \n\nThis power will allow us to gain the upper hand against the dreadlord and the Burning Legion, and I ask you to be the first to tap into it.", completion = "Your artifact is well on its way to reaching its true potential, but even with this power you will not be able to fight the Legion alone.\n\nWe will need to begin recruiting other mages to our cause. Unfortunately, the protective wards surrounding the hall may be prohibitive to this. \n\nAfter all, I cannot personally teleport every one of them here.\n\nHowever, a solution to this particular problem might be right under our noses.", objectives = "Use the Forge of the Guardian to unlock the first trait for your artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41126] = { id = 41126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Flotsam - twh" }
quests[41127] = { id = 41127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunksnout Infestation" }
quests[41128] = { id = 41128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valhallas - Vignette: Earlnoc - MRN" }
quests[41129] = { id = 41129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alturas Wrong Answer" }
quests[41130] = { id = 41130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Fear the Weeper" }
quests[41134] = { id = 41134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Jetsam - twh" }
quests[41135] = { id = 41135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Cora'kar - twh" }
quests[41136] = { id = 41136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Har'kess - twh" }
quests[41137] = { id = 41137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall of the King", description = "All that remains is the Sea Giant King.\n\nPlace our banner upon his beach and draw him out of the sea. Once he has revealed himself, use the trident to wound him.\n\nThere is a derelict boat that washed up on the shore. Use that to quickly get to the king's island.\n\nGird your loins, {name}. This fight will not be easy.", objectives = "Place the Jandvik Banner on the Sea Giant King's island to draw him out and defeat him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41138] = { id = 41138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Shal'Aran", description = "With leyline energy feeding in from Anora, this chamber can begin to awaken.\n\nIt will be a slow process, and we must take care to mask this activity from our enemies, a process which itself requires enormous effort and focus.\n\nFurthermore, there is the conundrum of actually consuming the mana in this form. A stream too weak is not enough to provide sustenance - too powerful and it would vaporize us.\n\nThere is much work to be done yet. For now, let us examine the feed.", completion = "I will call upon you again, I am sure.", objectives = "Examine the Leyline Feed in Shal'Aran with Arcanist Valtrois.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41139] = { id = 41139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key Is Around Here Somewhere...", description = "Well aren't ye a sight fer sore eyes!\n\nIt's no use tryin' to bust open this cage, this one needs a key!\n\nNow, I know what yer thinkin', \"How is it possible that the Burnin' Legion could capture a dwarf as mighty as ol' Angus here.\"\n\nYe can rest easy knowin' I let myself be captured. I'm here to rescue a dear friend o' mine, an' gettin' captured was the only way!\n\nI had the key in me pocket... but it musta' fell out.\n\nIt's  errm... around here somewhere.\n\nA felhunter ate it a wee while back...", progress = "Did ye find the key?", completion = "Ye found the key! Quickly, see if it fits...\n\nAye, that's the one! Ye did it!", objectives = "Find the Reinforced Cage Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41140] = { id = 41140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search and Rescue!", description = "We've got to find Brambley before it's too late!\n\nOl' Brambley an' I have been fightin' side by side since the Third War. When the Burnin' Legion invaded, we didn't think twice about coming to the Broken Isles.\n\nFightin' is what we do best!\n\nDuring the battle ol' Brambley got caught too deep an' got himself captured. Now we've got to rescue him!\n\nLast I saw, the demons were keeping him in a prison cell not far from here... let's go!", progress = "Have you found the key yet?", completion = "It's good to finally be free from this dreadful cage. As thanks, I will keep my word to you and your grotesquely hairy friend.", objectives = "Find Brambley Morrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41141] = { id = 41141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Conjuror's Duty", description = "I don't know about you but I'm ready to get this show on the road. This place is nice and all, but it's a bit stuffy.\n\nI'll see what I can do to get some more mages in this group of yours. You go ahead and check the map over there. It'll help you plan your first moves.", completion = "Alright, then! I can get started recruiting, and you can get to taking the fight to the demons!\n\nYeah, I know I'm letting you take the easy job, but hey, what are friends for?", objectives = "Use the Scouting Map to choose your first zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41142] = { id = 41142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Khory - twh" }
quests[41143] = { id = 41143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mglrgrs Of Our Grmlgrlr", description = "Mlrg...mglrmlr...\n\nGmlrgmlr mglrml gmlrg! Mlrgrlgr!\n\n<Mrgrglilgrl points at the trail of spiderwebs leading out of the ruin.>", completion = "Mlrgmlr rmlgml! Mrlmgrlg gmlrmlrg, grmlgmlr lmrglgr mlgmrlr. Mlgrmlgr grmlmgl, Mrgrlilgrl...", objectives = "????", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41144] = { id = 41144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the River" }
quests[41145] = { id = 41145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water of Life" }
quests[41146] = { id = 41146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elegant Design", description = "Amateur merchants complain about supply and demand. Masters create their own.\n\nYou have done well retrieving the last two pieces I requested, but they are baubles compared to this.\n\nYour target is the Lady Anastae, and she has something very valuable of mine: A design for a masterwork gem cut. \n\nGo and get it from her by any means necessary, but take care. She is a master manipulator and will tell you all manner of lies.", progress = "What do you want?", completion = "Lespin shall pay for his crimes!", objectives = "Convince Lady Anastae to give you the Gemcutter's Tome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41147] = { id = 41147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Other City of Mages", description = "Akazamzarak should be back from Dalaran with a new recruit to the Tirisgarde.\n\nThey await your return at the Hall of the Guardian." }
quests[41148] = { id = 41148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispensing Compassion", description = "There is much you need to learn about our city.\n\nFirst and foremost, Arcwine. It is the vehicle by which we imbibe the Nightwell's energies. Without it, we wither and die.\n\nPalace lackeys have seen fit to ration it, thinking this will control us. Keep us quiet, complacent.\n\nI would like you to look for those in need near the tavern. You will find many, but those most desperately afflicted by this rationing will be obvious.\n\nTake this flask. Revive them. Tend to their suffering.", progress = "Have you served those who suffer?", completion = "Your eyes are opening to our reality. I can see it in your expression. Good.", objectives = "Offer Arcwine to suffering citizens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41149] = { id = 41149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Re-Warding Effort", description = "<This small device of elegant nightborne design crackles gently with arcane power.\n\nKel'danath's notes mention wards that keep the withered at bay. It seems he found some form of spellcasting that does not tempt their ravenous appetite for magic.\n\nThese may prove useful in your search for the missing arcanist.>", completion = "<The ward snaps to life, giving you a slight pinch. Kel'danath must have put great care into developing a spell that would scare the withered away without harming them.>", objectives = "Activate 4 Arcane Wards in Ambervale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41153] = { id = 41153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revil Defeated" }
quests[41155] = { id = 41155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Riders", description = "There's a sewer grate along the edge of the river leading to catacombs underneath Karazhan. I've never paid it much attention, but it could be where the spirits are directing us.\n\nTo think, the Dark Riders may have been under our noses this entire time! Come, let us see where this leads.", progress = "Did you find what you seek, {class}?", completion = "Though I'll admit I may not have been able to do this alone, I will not forget the transgressions that happened today.\n\nYou have what you came for, {class}. I think it is time you were on your way.", objectives = "Defeat the Dark Riders in the Karazhan Catacombs and claim Ulthalesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41156] = { id = 41156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power Possessed", description = "Our goals have been met, warlock, and it is time we part ways.  I think I will be glad to see the last of you.\n\nGo on, return to your dark masters. We are done here.", completion = "Friend has the weapon? \n\nYes, Calydus can feel its power!", objectives = "Return to Calydus in The Underbelly in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41157] = { id = 41157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Studies", description = "Stormheim is steeped with artifacts from tha War of the Ancients. Demon artifacts ta be exact.\n\nI think these artifacts can clue us into some knowledge about their leader, Sargeras. I've already found some fragments to a titan disc, but need ta find the rest of 'em.\n\nI need ya ta dig around Stormheim and see if ye can find any more fragments so we can reassemble the disc.", progress = "With so many demon artifacts buried here, it's a wonder this place is as vibrant as it is.", completion = "<Brann takes the fragments and begins reassembling them.>\n\nWell, ye definitely found more o' the Titan Disc, but ye found something else too.\n\nHere, take a look at that!", objectives = "Survey digsites in Stormheim and bring Brann back 200 War of the Ancients Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41158] = { id = 41158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of the Fjords", description = "{name}, have you seen my ledger around here? I seemed to have misplaced it when I was stowing some canopic jars.\n\nOh, nevermind. Brann Bronzebeard has sent for you though. He's in Stormheim continuing his research.\n\nMake your way out to him and let him know I'm still waiting on those flayed-skin chronicles he found.", completion = "I'm gettin' closer to finding another piece of the titan relic, an' I need yer keen eyes.", objectives = "Meet with Brann Bronzebeard in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41159] = { id = 41159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Process of Elimination", description = "With so many places ta dig up fragments, it's become quite a pain figuring out where ta look for more of the titan disc.\n\nI have a plan though. I need ye ta eliminate potential areas where the disc could exist so we can narrow down where in Stormheim it might exist.\n\nYou take part of the area an' I'll take the other part. Meet back here if ye find anythin'.", completion = "Did ye run into any imps while ye were out diggen? Those blasted demons kept poppin' up on me!\n\nAlright, if ye dinnae find the disc at any o' those places, then there's but one place left ta look.", objectives = "Dig around Stormheim until you find a piece of the Titan Disc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41160] = { id = 41160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth to Earth", description = "From the earth comes strength, and such strength can be imbued into weapons of power.\n\nYou have the look of one who seeks to know how to create such weapons.\n\nThere are creatures that still inhabit this dying planet who bear such strength. Bring me their cores and I shall trade you the knowledge you seek.", progress = "There are also those who use such cores for more than mere forging. Be weary of such beings.", completion = "It would appear the earth trembled at YOUR power instead. Well done, champion.\n\nAs we agreed, here are your prizes in exchange for the cores.", objectives = "Recover a Cardinal Stone Core, a Cardinal Earth Core, and a Cardinal Lava Core for Lunelli. Bring them back to her in Shattrath when you have all three.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41161] = { id = 41161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Frying Pan", description = "Oh hello, {name}. I tell you, ever since I was given this shop, it's been nothing but a headache. I can't seem to ever find what I'm looking for.\n\nWhich reminds me, Brann Bronzebeard has sent for you. He's in Azsuna tracking down more pieces of whatever it is he's searching for.\n\nNow where'd those pewter drinking cups go...", completion = "I'm close, {name}. I can feel it in me bones!", objectives = "Meet with Brann in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41162] = { id = 41162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Into the Fel Fire", description = "I found something, {name}. Well, a couple of things actually.\n\nFirst I found an ancient text talking about a demon who harnessed the power of the titan disc I've been searching for.\n\nThen I found a device which supposedly is used to summon 'im! Only, it's missin' some pieces from what I can make out.\n\nI'm sure if we survey around Azsuna some more, those missin' pieces are sure ta turn up.", progress = "From what I can make out, I think there's only seven or eight parts we need...", completion = "Aye, that's all of 'em, lad. I'll just fix this up and we'll see what happens...", objectives = "Survey digsites in Azsuna and find 10 missing Parts of the Infernal Device and bring them back to Brann.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41163] = { id = 41163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apocalypse Bringer", description = "Right, well, I managed to piece the device back together.\n\nI guess I'll jes' turn it on when you're ready and we'll see what happens, yea?", progress = "Be ready for anything, lad.", completion = "Well that was a bit... eh... underwhelming. But hey, at least we got a piece o' tha titan disc!", objectives = "Talk to Brann when you're ready to activate the device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41164] = { id = 41164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Closer", description = "{name}! I just heard that Brann Bronzebeard - that crazy, titan-obsessed dwarf - has decided to go hunting for his precious disc in Suramar.\n\nTalk about the last place you'd want to go digging around, given the current events.\n\nI'm sure he could use your help.", completion = "There's demon stink all over this place. But there's also a lot of clues as to where a piece of the titan disc is!", objectives = "Meet with Brann in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41165] = { id = 41165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deciphering Demonology", description = "I found a piece of what appears to be a key to something. I'm certain I can restore it if we can find the other bits.\n\nAfter that, we need to figure out what it's a key to. An' I think I know how to do that.\n\nI've been studying some of the artifacts I've found, and they seem to be pointing to a hidden chamber. I jes' need some more artifacts to study.", progress = "How goes the search?", completion = "I'm startin' ta think you may be as good an archaeologist as I am. But don't let that go ta yer head, lad.\n\n<Brann lets out a chuckle and begins to study the artifacts you brought him.>\n\nAye, that's it! I know where the chamber is. And once I've reassembled tha key, we're in business.", objectives = "Crate artifacts into 5 Restored Artifacts and find 5 Chamber Key Fragments and bring them to Brann.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41166] = { id = 41166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Secrets", description = "I fixed the key and am ready to open the chamber.\n\nMeet me there when you have a chance and we'll discover what waits inside together!", progress = "I always love a good adventure!", completion = "A piece of the titan disc and a jar of blood. Well it's no wonder the elves locked this place up nice'n tight.\n\nI'll take me disc piece and you can do whatever ye want with that blood.", objectives = "Meet Brann at the entrance to the secret chamber. Once inside, stay close to Brann in case anything happens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41167] = { id = 41167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Fragments", description = "Brann Bronzebeard has requested that I send him more surveying equipment, but I just don't have the time.\n\nWould you be a dear and take this crate to him, {name}? I'd truly appreciate it.", completion = "Me equipment? Thanks, {name}!\n\nYe know, it's a good thing ye're here. This place gives me tha willies!", objectives = "Deliver the crate of surveying equipment to Brann in Val'sharah.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41168] = { id = 41168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purple Hills of Eredath", description = "Now that we're re-supplied, we can get back ta work.\n\nI found something here that I think ye'll be interested in. It's a page of a book talking about the world of Argus. But before the demons destroyed it.\n\nAnyway, it's been me experience that if ye find one of something, there's sure ta be more of it around.\n\nKeep lookin' around Val'sharah for more of these pages and bring what ye find back ta me. And take the page I found with ya so ye know what yer lookin' fer.", progress = "I can't wait to read the rest of that story.", completion = "<Brann skims over the book you've compiled.>\n\nSo where's the last chapter?", objectives = "Find the remaining pages of The Purple Hills of Eredath and assemble them into the final book. Return the book to Brann when you have finished.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41169] = { id = 41169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: Through the Fog", description = "I can't believe that after all that searchin' ye did, it's still missing a chapter!\n\nI'm willin' ta bet that those satyrs got a hand on it and took it somewhere. Probably somewhere dark where no one could find it.\n\nI've heard rumors of a place, the Darkheart Thicket they call it, where the strongest of the satyrs are.\n\nIf I had ta guess, I'd say ye need to go there and look around fer it.", progress = "A world of nightmares is nowhere where anyone should have ta go to.", completion = "Oh ho! Ye found the missing chapter AND a piece of me titan disc?!\n\nThis truly is a day of celebration. I'll let ye have the book, and ye can tell me what 'appened at tha end of it.", objectives = "Obtain the Final Chapter of The Purple Hills of Eredath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41170] = { id = 41170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Relic Renewed", description = "Very good, very good! Now that we have all the pieces, it's time to put this disc back together!", progress = "Jes a moment, lad...", completion = "After all that time, and we're still missing one piece!\n\nI swear the gods are workin' against me on me quest, {name}.\n\nOh well, back ta work! And here's a little somethin' for all the hard work ye've done fer me.", objectives = "Observe Brann as he puts the Titan Disc back together.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41171] = { id = 41171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reliquary Calls", description = "Tae'thelan of the Reliquary has asked me to send anyone who may be able to help them in Azsuna.\n\nSeeing as how you happened into my shop purely by coincidence, I thought you'd be willing to go, {name}.\n\nBack to work for me though. So much to do and so little help.\n\n<Dariness lets out a sigh.>", completion = "I ask for an archaeologist and they send an adventurer. Or perhaps you are both.\n\nEither way, let's get to work.", objectives = "Meet with Tae'thelan Bloodwatcher in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41172] = { id = 41172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of My Ancestors", description = "This land holds many secrets and many artifacts of ancient times.\n\nFrom what I've been able to discern there's an artifact of great power close to here. I just need to narrow down its location.\n\nI'd like you to dig up more artifacts and learn what you can. When you feel you've done enough research, come back to me and share your knowledge.", completion = "<Tae'thelan listens to your recount of what you learned.>\n\nVery interesting. If what you've said is true, then I believe I know where the location of the artifact is.", objectives = "Complete 25 Highborne Archaeology Projects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41173] = { id = 41173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Beacon of Hope", description = "I've marked the location of the artifact on your map. It's in a rather hostile location, so I'd like you to go there and find it.\n\nWhen you've recovered it, bring it back to me so I can discern its power.", progress = "Perhaps we can use this artifact to turn the tide of this war in our favor.", completion = "Let's see what you've found.\n\n<Tae'thelan studies the artifact for some time and lets out a sigh.>\n\nUseless. It's nothing more than a star field generator. Probably from some academy before the war.\n\nYou can have it back, {name}. I have no use for it.", objectives = "Go to the location Tae'thelan marked on your map and survey the area until you find the artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41174] = { id = 41174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worth Its Weight", description = "{name}, if you were a crate of black trilobites, where do you think I would have put you?\n\n<Dariness begins looking around the shop.>\n\nOh, that reminds me. Tae'thelan has requested your presence. He's onto something in Suramar and needs your help.", completion = "{name}, good to see you.\n\nI was hoping that the elves here would be a bit more... willing to let us inspect their artifacts, but such is not the case.\n\nAnd that's where you come in.", objectives = "Meet with Tae'thelan in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41175] = { id = 41175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fit for an Elven Queen", description = "The nightborne have dropped their shield allowing us to penetrate their city and learn their secrets.\n\nOne such secret I've discovered is a crown of immeasurable power.\n\nI'd like you to find this crown and report back to me on what it does.", completion = "You found it?\n\n<Tae'thelan listens as you explain about the missing jewels.>\n\nI see. So the crown was just a vessel and the jewels are the true source of power.", objectives = "Fight your way through Suramar into the chamber that holds the crown. Inspect the crown and report your findings back to Tae'thelan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41176] = { id = 41176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sifting Through the Rubble", description = "Then I believe it's clear what we must do next. Find the jewels.\n\nThey're bound to be here somewhere in Suramar, so we better start looking.\n\nI'll coordinate the search from here, while you and my assistants look for the jewels.", progress = "What's the status on the search for the jewels?", completion = "<Tae'thelan takes the jewels from you and looks them over closely.>\n\nThere may have been power in them once, but it's been all but drained. These are just pretty jewels now.\n\nHere, take them. Consider them payment for your services here.", objectives = "Survey different areas around Suramar until you find the 6 missing Jewels of the Crown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41177] = { id = 41177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Archaeology", description = "I'm not sure if you're in on this, but the Reliquary has commissioned the goblins to help them with uncovering artifacts in this land.\n\nI'd like you to go and see if there's any validity to this rumor... and I'd also be interested to know the results.", completion = "{name}, you're just in time to test out a new method I've been working on.", objectives = "Meet with Tae'thelan in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41178] = { id = 41178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Results", description = "As you may or may not have heard, I've been working with the goblins on using a new way of uncovering our artifacts.\n\nAnd if you know anything about goblins, you know that I'm talking about explosives.\n\nWe've only run a few tests here at my camp, but I would appreciate your help in testing this method out in the field.\n\nI've marked a location on your map that has some particularly difficult digs.", progress = "The working theory is that due to the amount of gunpowder that's being used, it should only produce a small shock to whatever the artifact has been encased in.", completion = "It was successful? That's excellent news!\n\nThis will speed up our process ten fold!", objectives = "Use the goblin explosives to free 500 Artifact Fragments from their geological prisons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41179] = { id = 41179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Once Was Lost", description = "That reminds me, I found a map to a chamber that may or may not hold something of value.\n\nIt doesn't seem to have any power associated with it, which is why I'm handing it over to you.\n\nHere, take some more explosives. They may help speed up the process of finding it.", completion = "<In the small chest, you find a chest with a raven's head etched into the lid.>", objectives = "Go to the location marked on the map and recover the artifact in question. Use the dynamite to uncover the artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41180] = { id = 41180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unspeakable Power", description = "{name}, I received an urgent message from the High Examiner requesting your presence.\n\nHe's finally found something powerful-- VERY powerful--and he wants your help in recovering it.\n\nBe careful down there, {name}. Tae'thelan can be a tad fanatical when it comes to artifacts that hold any sort of energy.", completion = "This is an exciting time, {name}. And you're going to get a front row seat to the show.", objectives = "Meet with Tae'thelan Bloodwatcher in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41181] = { id = 41181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narrowing Down", description = "I was right about the nightborne here having objects of great power. I found an ancient text referring to such an object called the Orb of Sciallax.\n\nFrom what I recall in studying the War of the Ancients, Sciallax was a demon lord who came to Suramar and offered the elves at the time a powerful artifact in return for their servitude to the Legion.\n\nI haven't discovered the exact location yet as to the whereabouts, but perhaps some digging can yield us an answer.", progress = "We must discover this artifact at all costs!", completion = "You've found the location? Then we must make haste.\n\nLet's go, {name}.", objectives = "Survey Suramar and uncover 10 Tattered Highborne Scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41182] = { id = 41182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Orb of Sciallax", description = "We'll need to hurry before the nightborne realize what we're after.\n\nI'm bringing the goblins along in case we run into any obstacles along the way.\n\nI've marked the location of the entrance to the chamber the Orb resides in on your map.\n\nMeet me there as soon as you're ready and we'll claim this artifact for our own.", progress = "Well?", completion = "NO! How did we fail? We were so close.\n\nThe explosives were too powerful. Those damned goblins ruined everything!\n\nNow only a handful of shards of what was once an object of unimaginable power remain.\n\nTake whichever one you want, {name}. I'd like to keep the rest to study.", objectives = "Meet Tae'thelan Bloodwatcher at the entrance to the chamber where the Orb of Sciallax is held. Once inside, set the charges on the casing and recover the artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41183] = { id = 41183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Academic Exploration", description = "{name}, good to see you. What do you think of my shop so far? Not too bad for just one person, huh?\n\nBy the way, High Examiner Tae'thalan has been digging around Azsuna, and asked that I send you to see him.\n\nKnowing him, he probably thinks he's found yet another world-shatteringly powerful artifact.", completion = "Hello, {name}. I'm glad you came.\n\nI've found something that may serve both of our interests.", objectives = "Meet with Tae'thelan in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41184] = { id = 41184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tried and True", description = "I have realized through experience that the old methods are usually the best and for good reason. I'm done with alternate means of digging for now, and wish to focus on the right way to do things.\n\nThat being said, I believe I've found a new powerful artifact and I'll do literally anything to have it.\n\nI've uncovered a fragment that appears to be a mold for a key. I now simply need the other pieces.", progress = "Have you recovered any of the other pieces yet?", completion = "Yes, I believe that's all of them.\n\n<Tae'thelan carefully reconstructs the mold.>\n\nAnd now we just need to forge a new set of keys.", objectives = "Find the remaining 15 Azsunian Key Mold Pieces and return them to Tae'thelan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41185] = { id = 41185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keys to Success", description = "I'd like you to take the mold to the blacksmith in Dalaran. Alard, I believe his name is.\n\nHave him help you forge a new set of keys.\n\nI found some writing on the back of the mold that may hold the answer to what these keys unlock. I'll stay here and try to translate the text.", progress = "The key is clearly tied to something here in Azsuna.", completion = "This is not a true key, but rather a device to provide access to the Nar'thalas Academy.\n\nThe academy was once a great location of knowledge for night elves to learn the arcane magics, but has long since long been destroyed.\n\nThe key is useless junk. You can keep it.", objectives = "Bring the mold to Alard Schmied in Dalaran and have him help you forge a new set of keys. Return to Tae'thelan when you have the finished set.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41186] = { id = 41186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "History of Highmountain", description = "Let's see, one... two... three... oh, hello {name}. Sorry I didn't see you come in.\n\nThings have been hectic around here. I could really use an assistant.\n\nI do have something for you though, a fellow archaeologist named Lessah has been asking for someone to help her in Highmountain.\n\nI thought you'd be the perfect person for the job.", completion = "Good to see you, {name}. I hope you're as interested about the tauren here as I am.", objectives = "Meet with Lessah in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41187] = { id = 41187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying Student", description = "The reason I sent for someone was that I've been having trouble keeping up with my research and training my assistant.\n\nI was hoping you might be able to show him the ropes again. Get him reacquainted with surveying.\n\nJust speak with him when you're ready to go.", completion = "Thank you for your help, {name}. Now perhaps you can help me with my research.", objectives = "Complete 20 successful surveys with Luron present.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41188] = { id = 41188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Lair: Misdirected", description = "I've been looking into the history of Huln Highmountain, a legendary warrior from the War of the Ancients whom this very land is named after.\n\nAllegedly some of his personal effects were carried here after his death and have been lost in time.\n\nAfter some digging around I believe I have discovered the location of one of his artifacts to be in a place called Neltharion's Lair.\n\nI'm no fighter, {name}, but you are. Will you go and recover this artifact for me?", progress = "If I've followed the clues correctly, then this could lead to one of Huln's weapons.", completion = "This is... not a weapon of Huln's. From the looks of it, I believe this to be the Spear of Rethu, an ancient tauren miner.\n\nI have no interest in this artifact, {name}. You may have it.", objectives = "Go to Neltharion's Lair and recover the Ancient Highmountain Artifact.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41189] = { id = 41189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Lead", description = "{name}, Lessah in Highmountain has been asking for you.\n\nApparently she's caught a lead on some ancient piece of armor that Huln Highmountain used to wear.\n\nWhen you can, make your way out to her.", completion = "There's more to this land than I ever realized, {name}. Now listen...", objectives = "Meet with Lessah in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41190] = { id = 41190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Eyes", description = "I've delved into the caves here and have discovered many ancient writings.\n\nThe most interesting I've found are resonating crystals, where the drogbar have resided. Unfortunately, they aren't on very good terms with the tauren here and this has hindered my research.\n\nI thought, should there be any trouble with the drogbar, that you'd be able to handle them.\n\nI'd like you to continue my research and discover what you can about Huln.", completion = "<Lessah listens to your recounting of the stories you discovered.>\n\nIf what you've said is true then that means that the piece I'm looking for is the necklace that Huln once wore.", objectives = "Interact with the two different resonating stones in Highmountain. Each stone requires 3 Highmountain Ritual-Stones to activate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41191] = { id = 41191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drogbar Deception", description = "According to my research and the information you gave me, I've isolated the location of the necklace.\n\nIt's deep in a drogbar cave, and I'm willing to bet they're not just going to hand it over to you, {name}.\n\nI need you to recover that necklace at any cost.", progress = "If only the drogbar were more reasonable.", completion = "<Lessah examines the necklace.>\n\nHow can this be?! All my research suggested that this belonged to Huln.\n\nI'm sorry, {name}, but this necklace is a creation of the drogbar. I'll give it back to you to do with it what you want.", objectives = "Recover the ancient necklace and bring it back to Lessah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41192] = { id = 41192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Path", description = "This new shop is shaping up quite nicely, I think. Still, there's so much left to organize.\n\n{name}, Lessah has requested your presence in Highmountain. Something about a moose?\n\nI'm not sure to what she's speaking of, but as soon as you have a chance, please go see her.", completion = "{name}, I've found an actual piece of something very close to Huln\n\nI believe that this is the very bone of Eche'ro, Huln Highmountain's animal companion!", objectives = "Meet with Lessah in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41193] = { id = 41193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying to Rest", description = "If I was able to find a bone fragment in what appeared to be a random location, then that means Eche'ro's bones must be scattered around Highmountain.\n\nWe must find his remains and give him the proper burial he deserved.\n\nOh, I'm sorry, in case you weren't aware, Eche'ro was Huln Highmountain's mount and companion.\n\nHe deserves to be honored as Huln once was.", progress = "We must see to it that his remains are given the respect they deserve.", completion = "What an honor, {name}. To think that Eche'ro's spirit will come to your aid should you need it... that is a great reward indeed.\n\nAnd for me, to witness the majesty of Huln himself! I shall continue to study him, and the glorious legacy he left behind.", objectives = "Find 600 Bone Fragments of Eche'ro and return them to Lessah in Highmountain. Then observe the burial ceremony Lessah performs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41194] = { id = 41194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remulos Tracker" }
