quests[41197] = { id = 41197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Got to Be Kitten Me Right Meow", description = "While you were dealing with the stray Owlkitten, I took a look around.\n\nIt seems these curious creatures have a habit of escaping their parents' watchful eyes - some are trapped across the road by a wandering Ettin. \n\nHe appears to have been... ahem... eating them.\n\nWe can earn Yowlon's blessing by bringing his children home.", progress = "Have you managed to rescue any?", completion = "They look so happy to be home. Excellent work.", objectives = "\"Herd\" 7 Lost Feathermane Kittens back home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
