quests[41213] = { id = 41213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifact XP - Cho'Zok" }
quests[41214] = { id = 41214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts Unknown", description = "Brambley... I still canna' believe it.\n\nI canna' leave the lad here... not in this place... not like this.\n\nHelp me find the rest of him, so I can take his remains back home where he belongs.\n\nWe'll give him a proper burial... it's what he deserves!", progress = "Aye, is that all of him? We aren't missing any parts are we?", completion = "<Angus wipes away a tear as he speaks.>\n\nBrambley, lad... I promise ye'll have tha' best burial money can buy! An' all the ale ye can drink...", objectives = "Collect Brambley Morrison's remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41215] = { id = 41215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Become The Hunted", description = "The trapper you slew was but one of many.\n\nThe Nightborne are subjugating the local creatures, creating a sort of pleasurable exhibit. I think we can strike them in two places at once.\n\nDescend upon these trappers, {race}. Let us teach them a lesson in respecting their prey.", progress = "With the number of trappers thinned, their ability to scout into Suramar will be sorely hampered.", completion = "Excellent work. They do not respect the hunt, so they must be reminded of their place.", objectives = "Slay 6 Nightborne Trappers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41216] = { id = 41216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival of the Fittest", description = "The collar you took from the trapper is simple, but effective. Affixing the collar to a target will make them complacent and obedient to their Nightborne masters. Lilryia was able to reverse the spell using the traps you found.\n\nThe magics in the collar can now be used to cancel out the other collars.\n\nHow about giving the Nightborne a reminder that nature always finds a way?", completion = "I could hear their cries and see the carnage from here! That will teach the Nightborne to enslave creatures. Have they fallen so far during all those years under the shield?", objectives = "Free 12 exhibits from the Menagerie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41217] = { id = 41217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nMuffinus Chromebrew will help oversee your training and adjustment to life on the surface. He's waiting for you on the stands across the road.", completion = "For a {race} who has spent so much time inside Gnomeregan, you look positively fit and healthy, {name}. That's good. Before we can complete what Operation: Gnomeregan began, we're going to need more hunters like you.", objectives = "Meet with Muffinus Chromebrew in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41218] = { id = 41218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", objectives = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41219] = { id = 41219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flourishing Foxflower" }
quests[41220] = { id = 41220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to Azsuna", description = "{name}, we must find a way to reseal the Tomb of Sargeras.\n\nI have uncovered information concerning an ancient relic, which might be the key to stopping the Legion.\n\nOur search begins on the ancient elven island of Azsuna. Long ago, it was where the Highborne elves of Suramar perfected their mightiest of magics. Now it is a cursed ruin.\n\nThe Illidari demon hunters have established a camp on the island. As they are the only people we know in the area, that is where we will begin.\n\nReady to take wing?", progress = "It would seem that we have arrived at the crucial moment.", completion = "As I suspected, the Illidari are holding the line against the Burning Legion, but just barely.\n\nWe must come to their aid, {name}.", objectives = "Speak with Archmage Khadgar to fly down to Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41221] = { id = 41221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Mardum", description = "The gateway is fully functional, {name}. Ooh, I am positively tingling with excitement!\n\nDo let Jace and the others know that we eagerly await your arrival. There's so much to do and ever so little time.\n\nYou will be joining us aboard, won't you?", completion = "This citadel was one of the Legion's most valuable assets - it will serve us well.", objectives = "Enter the Illidari Gateway to board the Fel Hammer in Mardum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41222] = { id = 41222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Pit!", description = "The felstalker pits?!\n\nThere's no time to waste, {name}!\n\n I canna' tell ye what the Burnin' Legion has planned for ol' Brambley, but it canna' be good!\n\nHurry! We've got to find him before the Burnin' Legion has their way with him!", progress = "We've got to get to the felstalker pits an' save Brambley!", completion = "It canna' be true!\n\nBrambley... my dear ol' friend! Why did ye have to go an' die?", objectives = "Escort Angus to Felmaw Cavern in Felsoul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41223] = { id = 41223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Foxflower", progress = "Have you brought the supplies we requested?", completion = "Many thanks, herbalist. This foxflower shall not be wasted." }
quests[41224] = { id = 41224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies Needed: Foxflower", progress = "Have you brought the supplies we requested?", completion = "Many thanks, {class}. This foxflower shall not be wasted." }
quests[41225] = { id = 41225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felwort" }
quests[41226] = { id = 41226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Out", description = "We cannot fight our way out of the Vault alone.\n\nTwo of your allies, Kayn Sunfury and Altruis the Sufferer, are imprisoned within this room. \n\nFree them with haste. Their strength will be of great use to us.", sourceObjective = "Free both Altruis the Sufferer and Kayn Sunfury.", sourceObjectiveStatus = "unverified-source-field" }
quests[41227] = { id = 41227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Cordana's Apex" }
quests[41228] = { id = 41228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxflower Cluster" }
quests[41229] = { id = 41229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chen Obtained" }
quests[41230] = { id = 41230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trapping Evolved", description = "The Nightborne are using magic for everything, even trapping.\n\nNighteyes saw them at work, laying down magical snares to capture prey rather than the kind our people use. \n\nBring me their traps so that I may study their make.", progress = "Do you have the snares, {race}?", completion = "These devices are peculiar. They are like the traps our hunters use, but can magically attract and trap nearby beasts.", objectives = "Collect 4 Arcane Traps for Lilryia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41231] = { id = 41231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apex Predator", description = "I have good news and bad news, {race}.\n\nThe bad news is that they somehow managed to capture and train a Devilsaur.\n\nThe good news is that it doesn't seem to have a collar and is tame. I imagine it must think that one of the Nightborne in there is its master. Find the pack leader and take him out, and we will set quite a beast upon them.", progress = "Did you find the alpha?", completion = "I saw everything from out here. That was... messy.", objectives = "Find and slay the Nightborne keeping Su'esh obedient.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41232] = { id = 41232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thick Ironhorn Hide" }
