quests[41255] = { id = 41255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowing The Seed", description = "Your weapon is ancient and powerful but it holds the potential to be so much more.\n\nTake this seed, it is all that remains of a forest that grew tall when the world was young. Plant it within the grove to the west and allow it to take root.\n\nWith its power both it and your weapon will be far more than they are alone.", completion = "Excellent. There's no time to waste.", objectives = "Plant the Seed of Ages in the Soft Soil within The Dreamgrove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41256] = { id = 41256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blast of Spice Fish", description = "I have an ingredient that will make my fruit irresistible.\n\nNot many remember the delicacy of manatrout liquor. Its pungent aroma, the unctuous mouthfeel...\n\nThe toads near the northern river concentrate this additive in their gizzards. Fetch some stomachs for me, and we will have plenty.", progress = "Daglir is young and foolish!", completion = "Manatrout was completely fished out of our harbors. Since the shield was raised all we have had of the liquor is memories on our palates.", objectives = "Collect Toad Gizzards for Keelay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41257] = { id = 41257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Cordana's Apex" }
quests[41258] = { id = 41258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruit of the Doom", description = "Now is the time to strike.\n\nShadowbloom has... potent digestive qualities. Go sprinkle some on Daglir's fruit bowls and watch the show.\n\nMeanwhile, I will use the manatrout liquor to cement my position as the premier fruit vendor in the city.", progress = "Daglir will be ruined after this.", completion = "Victory tastes sweeter than any dish, even one of mine.", objectives = "Poison 3 Bowls of Fruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
