quests[41307] = { id = 41307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Glitters", description = "Now that the shield is down, the older settlements outside the city have been on my mind.\n\nDid you know that I helped create the filigree on the arcane lamps that are used throughout the city? A simple task, one of my first...\n\nNo matter. Nostalgia is the enemy of progress. The lamps are made of material better used in my new works.\n\nThose wretched harpies probably have several decorating their nests. Bring back any you find.", progress = "Can you imagine, a Lespin original hiding under a pile of leaves? What a waste.", completion = "Excellent. I shall have these melted down and turned into ingots for my next batch of commissions.", objectives = "Retrieve 6 Arcane Glowlamps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41308] = { id = 41308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Border Reinforcements" }
quests[41309] = { id = 41309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangelrath", description = "The demonic beast that stands before ye, must be the one that devoured ol' Brambley...\n\nJust look at it, lying there with a full belly! I canna abide it any longer, {name}! We must slay the foul creature and avenge Brambley!\n\nWe've come this far already, {class}.\n\nAre ye with me?!", completion = "It's good to see a friendly face, I don't know how much longer I could have held out on my own!", objectives = "Defeat Mangelrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41310] = { id = 41310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Border Reinforcements" }
