quests[41320] = { id = 41320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pry It From Their Cold, Feral Claws", description = "The shield being lowered presents a unique opportunity for new styles.\n\nFeathers, bone and other primitive materials are suddenly fashionable again. Who would have thought they could grow tired of my masterpieces?\n\nVenture out of the city and collect necklaces from the harpies on the southern cliffs. Etching my mark into them should net me a tidy profit.", progress = "Do you have my necklaces? They are of no use to me on the necks of those... creatures.", completion = "Those wretched creatures are a scourge on our beautiful lands. At least they had good taste in their accessories.\n\nOr maybe they just like shiny things.", objectives = "Retrieve 8 Harpy Necklaces for Lespin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
